import { loadFont } from "@remotion/google-fonts/Onest";
import React, { forwardRef, useEffect, useId, useImperativeHandle, useLayoutEffect, useMemo, useRef, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, interpolateColors, spring, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Chrome parks a glyph raster on a whole pixel vertically for as long as the
// matrix that carries it is axis-aligned, so text under a slow transform
// clicks along pixel by pixel. A lean too small to see takes it off that grid.
//
// A transform that carries text is marked, and told when it moves:
//
//   const glide = useGlide();
//   transform: `scale(${s})${glide(moving)}`
//
// The mark changes nothing by itself. After every frame the blocks of text
// under a marked transform get the lean: each about its own centre, and each
// by no more than its size on the screen needs. A card, a hairline or an image
// is fine under a transform as it is, so they stay level.
//
// Text leans while its transform moves, and it keeps the lean at rest when it
// rests off the pixel grid (a scene shown smaller in a player, a camera that
// holds at 1.03): dropping the lean there would snap it to the nearest pixel,
// up to half a pixel in one frame, and picking it up would snap it back. Text
// that rests on the grid loses the lean without moving, so a scene at rest at
// full size is drawn exactly as it would be without any of this.

/**
 * Returns `glide(moving)`: append it to a transform that carries text, with
 * `moving` true on the frames where that transform changes.
 *
 * Everything else lives inside this one closure: the build of Studio
 * elements pastes this file whole into the component that uses it, where a
 * second `LEAN` or `lean` at the top level would collide.
 */
const useGlide = (() => {
  /** What `glide(false)` adds to a transform: an identity matrix, to find it by. */
  const AT_REST = " matrix(1, 0, 0, 1, 0, 0)";
  /** `glide(true)` adds it twice. */
  const MOVING = AT_REST + AT_REST;
  const MARKED = `[style*="${AT_REST.trim()}"]`;
  // Text leaves the grid once the matrix leans x into y by half of 1/1024 in
  // device pixels (Skia rounds the glyph matrix to 1/1024). A fifth over it.
  const LEAN = 0.6 / 1024;
  // Past this the text is a speck on the screen; it is left alone.
  const STEEPEST = 5;
  // How far from a whole pixel text may rest and still count as on the grid:
  // the jump it makes when the lean goes is no bigger than this.
  const ON_GRID = 0.05;

  /** The linear part of a 2D matrix: x' = a·x + c·y, y' = b·x + d·y. */
  type Lin = [a: number, b: number, c: number, d: number];
  const LEVEL: Lin = [1, 0, 0, 1];
  const times = (m: Lin, n: Lin): Lin => [
    m[0] * n[0] + m[2] * n[1],
    m[1] * n[0] + m[3] * n[1],
    m[0] * n[2] + m[2] * n[3],
    m[1] * n[2] + m[3] * n[3],
  ];
  const turned = (degrees: number): Lin => {
    const t = (degrees * Math.PI) / 180;
    return [Math.cos(t), Math.sin(t), -Math.sin(t), Math.cos(t)];
  };
  const offWhole = (n: number) => Math.abs(n - Math.round(n));

  type Block = HTMLElement | SVGTextElement | SVGSVGElement;
  let leant: Block[] = [];
  // Fonts arrive after the first pass and change what is laid out where, with
  // no render to follow: a block or a marked element that changes size is read
  // again before the frame is painted.
  let watcher: ResizeObserver | undefined;
  const watched = new WeakSet<Element>();
  const watch = (el: Element) => {
    if (watched.has(el)) return;
    watched.add(el);
    watcher ??= new ResizeObserver(() => lean());
    watcher.observe(el);
  };

  const depthOf = (el: Element) => {
    let depth = 0;
    for (let up = el.parentElement; up; up = up.parentElement) depth += 1;
    return depth;
  };

  /** The nearest box around a text node that a transform applies to. */
  const blockOf = (node: Node): Block | null => {
    for (let el = node.parentElement; el; el = el.parentElement) {
      if (el instanceof SVGElement) {
        const text = el.closest("text");
        if (!(text instanceof SVGTextElement)) return null;
        // Text that only shapes a mask or a clip is not drawn where it stands
        // and cannot turn by itself: its whole drawing leans for it.
        if (!text.closest("defs, mask, clipPath, pattern, symbol, marker"))
          return text;
        let drawing = text.ownerSVGElement;
        while (drawing?.ownerSVGElement) drawing = drawing.ownerSVGElement;
        return drawing;
      }
      if (!(el instanceof HTMLElement)) continue;
      const { display } = getComputedStyle(el);
      if (display !== "inline" && display !== "contents") return el;
    }
    return null;
  };

  /** One pass over the page: what every element's own transforms do. */
  function reader(given: Map<Element, number>) {
    type Own = {
      /** `scale` and `transform`, without the `rotate` property. */
      lin: Lin;
      /** `rotate`, in degrees: a lean given in this pass, or the scene's own. */
      turn: number;
      /** How far down it is moved, and by what whole factor it is scaled from
       * its top left corner; null when it does anything else. */
      carry: { dy: number; k: number } | null;
    };
    const lens = new Map<Element, boolean>();
    /** Whether an element shows its children in perspective. */
    const lensOn = (el: Element | null): boolean => {
      if (!el) return false;
      const seen = lens.get(el);
      if (seen !== undefined) return seen;
      const style = getComputedStyle(el);
      const result =
        style.perspective !== "none" ||
        (style.transformStyle === "preserve-3d" && lensOn(el.parentElement));
      lens.set(el, result);
      return result;
    };
    const own = new Map<Element, Own | null>();
    const ownOf = (el: Element): Own | null => {
      const seen = own.get(el);
      if (seen !== undefined) return seen;
      const style = getComputedStyle(el);
      const m = new DOMMatrixReadOnly(
        style.transform === "none" ? "" : style.transform,
      );
      const scale = style.scale === "none" ? [] : style.scale.split(" ");
      const sx = scale.length ? Number.parseFloat(scale[0]) : 1;
      const sy = scale.length > 1 ? Number.parseFloat(scale[1]) : sx;
      const rotate = style.rotate === "none" ? [] : style.rotate.split(" ");
      let result: Own | null = null;
      // Seen in perspective, text is drawn on a layer of its own: not ours. A
      // turn out of the plane without perspective lands flat on the screen,
      // and text under it snaps like any other.
      // A push along z alone, or a half turn, leaves it flat even under a lens.
      const inPerspective =
        Math.max(Math.abs(m.m14), Math.abs(m.m24), Math.abs(m.m34)) > 1e-9 ||
        (Math.max(
          Math.abs(m.m13),
          Math.abs(m.m31),
          Math.abs(m.m23),
          Math.abs(m.m32),
        ) > 1e-6 &&
          lensOn(el.parentElement));
      if (!inPerspective && rotate.length < 2) {
        // The `scale` property acts on what `transform` has produced.
        const lin: Lin = [m.a * sx, m.b * sy, m.c * sx, m.d * sy];
        const moved =
          style.translate === "none"
            ? 0
            : (style.translate.split(" ")[1] ?? "0px");
        const k = Math.round(lin[0]);
        const whole =
          m.is2D &&
          k >= 1 &&
          Math.abs(lin[0] - k) < 1e-4 &&
          Math.abs(lin[3] - k) < 1e-4 &&
          Math.abs(lin[1]) < 1e-5 &&
          Math.abs(lin[2]) < 1e-5 &&
          rotate.length === 0 &&
          (moved === 0 || moved.endsWith("px")) &&
          // Scaled about its corner, a box stays where layout put it.
          (k === 1 || /^0(px)? 0(px)?/.test(style.transformOrigin));
        result = {
          lin,
          turn: rotate.length ? Number.parseFloat(rotate[0]) : 0,
          carry: whole
            ? { dy: sy * m.f + (moved === 0 ? 0 : Number.parseFloat(moved)), k }
            : null,
        };
      }
      own.set(el, result);
      return result;
    };
    const down = new Map<Element, Lin | null>();
    /** Everything from the page down to and including this element. */
    const linDown = (el: Element | null): Lin | null => {
      if (!el) return LEVEL;
      const seen = down.get(el);
      if (seen !== undefined) return seen;
      const above = linDown(el.parentElement);
      const mine = above && ownOf(el);
      const result =
        above && mine
          ? times(times(above, turned(given.get(el) ?? mine.turn)), mine.lin)
          : null;
      down.set(el, result);
      return result;
    };
    const carried = new Map<Element, { dy: number; k: number } | null>();
    const carryDown = (
      el: Element | null,
    ): { dy: number; k: number } | null => {
      if (!el) return { dy: 0, k: 1 };
      const seen = carried.get(el);
      if (seen !== undefined) return seen;
      const above = carryDown(el.parentElement);
      const mine = above && !given.has(el) ? ownOf(el)?.carry : null;
      const result =
        above && mine
          ? { dy: above.dy + above.k * mine.dy, k: above.k * mine.k }
          : null;
      carried.set(el, result);
      return result;
    };
    return { ownOf, linDown, carryDown };
  }

  /**
   * Whether text in an SVG rests on the grid: it is placed wherever it is told
   * to, so only when it is shown one to one and its baseline happens to land on
   * a whole pixel. `lands` is where its own space lands on the screen.
   */
  function restsOnGrid(text: SVGTextElement, lands: DOMMatrix | null) {
    if (!lands) return false;
    const dpr = window.devicePixelRatio;
    const style = getComputedStyle(text);
    const k = lands.d * dpr;
    const y = text.y.baseVal.numberOfItems
      ? text.y.baseVal.getItem(0).value
      : 0;
    return (
      text.y.baseVal.numberOfItems <= 1 &&
      text.dy.baseVal.numberOfItems === 0 &&
      !text.querySelector("tspan[y], tspan[dy], textPath") &&
      /^(auto|alphabetic)$/.test(style.dominantBaseline) &&
      /^(auto|baseline)$/.test(style.alignmentBaseline) &&
      Math.abs(lands.b) < 1e-6 &&
      Math.abs(lands.c) < 1e-6 &&
      Math.round(k) >= 1 &&
      offWhole(k) < 2e-3 &&
      offWhole((lands.d * y + lands.f) * dpr) < ON_GRID
    );
  }

  /**
   * The angle that takes a block off the grid, given what is above it (`above`)
   * and what its own transform does (`own`), both in device pixels: the lean is
   * a turn between the two. 0 when the block leans enough as it is, null when
   * no sane angle would do.
   */
  function angleFor(above: Lin, own: Lin): number | null {
    // y from x of `above · turn(θ) · own` is p·sin θ + q·cos θ.
    const p = above[3] * own[0] - above[1] * own[1];
    const q = above[1] * own[0] + above[3] * own[1];
    if (Math.abs(q) >= LEAN) return 0;
    if (Math.abs(p) < 1e-9) return null;
    // Along the turn the scene already has, so the two never cancel out.
    const sine = ((q < 0 ? -LEAN : LEAN) - q) / p;
    if (Math.abs(sine) > Math.sin((STEEPEST * Math.PI) / 180)) return null;
    return (Math.asin(sine) * 180) / Math.PI;
  }

  function lean() {
    for (const el of leant) {
      el.style.removeProperty("rotate");
      if (el instanceof SVGElement) el.style.removeProperty("translate");
    }
    leant = [];
    const zones = document.querySelectorAll<HTMLElement | SVGElement>(MARKED);
    if (zones.length === 0) return;
    // Each block of text under a mark, and whether any transform above it moves.
    const blocks = new Map<Block, boolean>();
    // The texts a whole drawing leans for.
    const standsFor = new Map<SVGSVGElement, SVGTextElement[]>();
    for (const zone of zones) {
      const moving = zone.style.transform.includes(MOVING.trim());
      const walker = document.createTreeWalker(zone, NodeFilter.SHOW_TEXT);
      for (let node = walker.nextNode(); node; node = walker.nextNode()) {
        if (!/\S/.test(node.nodeValue ?? "")) continue;
        const block = blockOf(node);
        // A block that turns by a property of its own is left to the scene.
        if (!block || block.style.rotate) continue;
        blocks.set(block, moving || (blocks.get(block) ?? false));
        const text = node.parentElement?.closest("text");
        if (block instanceof SVGSVGElement && text instanceof SVGTextElement)
          standsFor.set(block, [...(standsFor.get(block) ?? []), text]);
      }
      watch(zone);
    }
    for (const block of blocks.keys()) watch(block);
    const dpr = window.devicePixelRatio;
    const scaled = (m: Lin): Lin => [
      m[0] * dpr,
      m[1] * dpr,
      m[2] * dpr,
      m[3] * dpr,
    ];
    // Outer blocks first: a block inside a leaning one takes only what it
    // still lacks, so leans never pile up. Everything is read before anything
    // is written; `given` stands in for the leans not yet on the page.
    const given = new Map<Element, number>();
    const { ownOf, linDown, carryDown } = reader(given);
    const writes: (() => void)[] = [];
    const ordered = [...blocks.keys()].sort((a, b) => depthOf(a) - depthOf(b));
    for (const el of ordered) {
      const moving = blocks.get(el) === true;
      if (el instanceof HTMLElement) {
        const above = linDown(el.parentElement);
        const mine = ownOf(el);
        if (!above || !mine) continue;
        if (!moving) {
          // Layout puts a baseline on a whole pixel wherever the box itself
          // sits, so text is on the grid when the transforms around it only
          // move it by whole pixels and show it one to one (or two, or three).
          const carry = carryDown(el);
          if (
            carry &&
            offWhole(carry.k * dpr) < 2e-3 &&
            offWhole(carry.dy * dpr) < ON_GRID
          )
            continue;
        }
        const angle = angleFor(scaled(above), mine.lin);
        if (!angle) continue;
        given.set(el, angle);
        writes.push(() => el.style.setProperty("rotate", `${angle}deg`));
        leant.push(el);
        continue;
      }
      if (el instanceof SVGSVGElement) {
        // A whole drawing: what it does itself is its own transform and the
        // scale of its viewBox, read off where it lands on the screen.
        const above = linDown(el.parentElement);
        const lands = el.getScreenCTM();
        const det = above ? above[0] * above[3] - above[1] * above[2] : 0;
        if (!above || !lands || Math.abs(det) < 1e-12) continue;
        if (
          !moving &&
          (standsFor.get(el) ?? []).every((text) =>
            restsOnGrid(text, text.getScreenCTM()),
          )
        )
          continue;
        const mine = times(
          [above[3] / det, -above[1] / det, -above[2] / det, above[0] / det],
          [lands.a, lands.b, lands.c, lands.d],
        );
        const angle = angleFor(scaled(above), mine);
        if (!angle) continue;
        given.set(el, angle);
        writes.push(() => el.style.setProperty("rotate", `${angle}deg`));
        leant.push(el);
        continue;
      }
      // Its drawing leans as a whole already.
      let drawing = el.ownerSVGElement;
      while (drawing?.ownerSVGElement) drawing = drawing.ownerSVGElement;
      if (drawing && given.has(drawing)) continue;
      // Text in an SVG is placed wherever it is told to, so it is on the grid
      // only when its baseline happens to land on a whole pixel.
      const frame = el.parentNode;
      if (!(frame instanceof SVGGraphicsElement) || el.style.translate)
        continue;
      const outer = frame.getScreenCTM();
      const whole = el.getScreenCTM();
      if (
        !outer ||
        !whole ||
        Math.abs(outer.a * outer.d - outer.b * outer.c) < 1e-12
      )
        continue;
      // What the text element itself does, in the space it is placed in.
      const mine = outer.inverse().multiply(whole);
      if (!moving && restsOnGrid(el, whole)) continue;
      const angle = angleFor(scaled([outer.a, outer.b, outer.c, outer.d]), [
        mine.a,
        mine.b,
        mine.c,
        mine.d,
      ]);
      if (!angle) continue;
      // An SVG element turns about the corner of its drawing. A move brings
      // the turn to the middle of the text instead.
      const box = el.getBBox();
      const [cx, cy] = [box.x + box.width / 2, box.y + box.height / 2];
      const [px, py] = [
        mine.a * cx + mine.c * cy + mine.e,
        mine.b * cx + mine.d * cy + mine.f,
      ];
      const [cos, sin] = [turned(angle)[0], turned(angle)[1]];
      const [tx, ty] = [px - (px * cos - py * sin), py - (px * sin + py * cos)];
      writes.push(() => {
        el.style.setProperty("rotate", `${angle}deg`);
        el.style.setProperty("translate", `${tx}px ${ty}px`);
      });
      leant.push(el);
    }
    for (const write of writes) write();
  }

  const useFrameEffect =
    typeof window === "undefined" ? useEffect : useLayoutEffect;

  function useGlide() {
    // No dependencies: the lean follows whatever this frame laid out.
    useFrameEffect(lean);
    return glide;
  }

  const glide = (moving: boolean) => (moving ? MOVING : AT_REST);

  return useGlide;
})();

const { fontFamily: sans } = loadFont("normal", {
  weights: ["500"],
  subsets: ["latin"],
});

interface TypoFixProps {
  wrong?: string;
  correct?: string;
  before?: string;
  after?: string;
  /** Frame the letters start hopping into their right places. */
  fixAt?: number;
  /** Color of the spell-check squiggle; overrides the theme. */
  errorColor?: string;
  accent?: string;
  /** Text color; overrides the theme ink. */
  ink?: string;
  /** Background fill in place of the lit ground; "transparent" drops it. */
  background?: string;
  /** Typeface for the line. Load it yourself; Onest by default. */
  fontFamily?: string;
  /** Film grain over the scene. */
  grain?: boolean;
  /** Size of the line, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  theme?: "dark" | "light";
  speed?: number;
}

// Onest 500 advance widths (1/1000 em) for ASCII 32–126, plus its kern pairs.
const ONEST_500 = [
  274, 283, 377, 662, 658, 831, 690, 230, 323, 323, 430, 564, 274, 460, 263,
  489, 663, 372, 564, 604, 634, 616, 623, 507, 623, 620, 263, 274, 564, 564,
  564, 519, 987, 684, 662, 707, 723, 614, 601, 724, 732, 272, 567, 641, 581,
  870, 749, 765, 638, 765, 668, 655, 578, 730, 694, 990, 618, 637, 604, 332,
  489, 332, 564, 457, 576, 559, 611, 556, 611, 574, 372, 611, 596, 230, 259,
  533, 230, 830, 596, 596, 611, 611, 380, 510, 369, 579, 543, 851, 530, 603,
  515, 394, 268, 394, 564,
];
const KERN_PAIRS = [
  "AA-15 AC18 AG18 AJ-20 AO18 AQ18 AS18 AT50 AU10 AV50 AW30 AY60 Av30",
  "Aw20 BV10 BW10 BX10 BY10 CA19 CJ-10 CV25 CX24 CY20 DA19 DC-15 DG-15",
  "DJ-10 DO-15 DQ-15 DS-15 DT10 DV25 DX30 DY20 Dd-10 FA50 FJ30 FT-20",
  "Fa30 Fc25 Fd25 Fe25 Fg25 Fo25 Fq25 Fs25 GA19 GJ-10 GT10 GV25 GX24",
  "GY20 JA10 KT-10 Ka10 Kv30 LA-20 LJ-30 LT40 LV50 LW40 LX-10 LY80 La-10",
  "Lc-10 Ld-10 Le-10 Lg-10 Lj-20 Lo-10 Lq-10 Ls-10 Lz-20 OA19 OJ-10 OV26",
  "OX24 OY26 PA52 PC-10 PG-10 PJ50 PQ-10 PS-10 PX25 PY15 Pa20 Pc10 Pd10",
  "Pe10 Pg10 Pj10 Po10 Pq10 Ps10 QA19 QJ-10 QT10 QV25 QX24 QY20 RY20",
  "Ra10 Rc10 Rd10 Re10 Rg10 Ro10 Rq10 Rs10 SA19 SJ-10 ST10 SV25 SX30",
  "SY20 TA54 TG10 TJ80 TQ10 TS10 TT-40 Ta60 Tc50 Td50 Te50 Tg50 Tm20",
  "Tn20 To50 Tp20 Tq50 Tr20 Ts50 Tu20 UA10 Ua20 Uc10 Ud10 Ue10 Ug10 Uo10",
  "Uq10 Us10 VA50 VC25 VG25 VJ80 VO26 VQ25 VS25 Va50 Vc50 Vd50 Ve50 Vg50",
  "Vm20 Vn20 Vo50 Vp20 Vq50 Vr20 Vs50 Vu20 Vz20 WA30 WJ30 Wa35 Wd25 XC24",
  "XG24 XO24 XQ24 XS30 YA60 YC20 YG20 YJ90 YO26 YQ20 YS20 Ya70 Yc70 Yd70",
  "Ye70 Yf20 Yg70 Ym30 Yn30 Yo70 Yp30 Yq70 Yr30 Ys70 Yu30 Yv30 Yw20 Yx20",
  "Yz30 bT50 bV50 bY70 bc-10 bd-10 bf10 bx10 cT50 cV50 cY70 cc-10 cf10",
  "cx10 eT50 eV50 eY70 ec-10 ef10 ex10 fc10 fd10 fe10 fg10 fo10 fq10",
  "fs10 jj-20 oT50 oV50 oY70 of10 ox10 pT50 pV50 pY70 pc-10 pf20 pt20",
  "px10 qj-20 rc10 rd10 re10 rg10 ro10 rq10 rs10 rt-30 sT50 sV50 sY70",
  "sc-10 sf10 st10 sx15 vA30 xc10 xd10 xe10 xg10 xo10 xq10 xs10",
].join(" ");
const KERN = new Map(
  KERN_PAIRS.split(" ").map((p) => [p.slice(0, 2), -Number(p.slice(2)) / 1000]),
);

const TRACK = -0.03;
const ASC = 0.97;
const LINE = 1.275;
const CAP = 0.708;
const SPACE = 0.274 + TRACK;

const ENTER_STAGGER = 3;
const ENTER_LEN = 18;
const SQUIGGLE_AT = 20;
const SQUIGGLE_LEN = 14;
const SWAP_AT = 44;
const SWAP_STAGGER = 1;
const TRAVEL = 20;
const RETRACT_LEN = 10;
const RULE_DELAY = 1;
const RULE_LEN = 10;
const HOLD = 36;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// Ground: gradients.sh "grain" (dark) and "smear" (light), a warm light
// from the top left, kept low so the type and the red squiggle stay crisp.
const THEMES = {
  dark: {
    bg: "#070505",
    fg: "#F5F1EC",
    dim: "#6A605B",
    error: "#FF5A4F",
    grain: 0.08,
    glow: "rgba(255, 216, 180, 0.36)",
    wash: [
      "rgba(224, 112, 59, 0.85)",
      "rgba(138, 44, 29, 0.62)",
      "rgba(43, 16, 21, 0.55)",
    ],
  },
  light: {
    bg: "#F5F2EC",
    fg: "#141212",
    dim: "#ABA39C",
    error: "#D9302C",
    grain: 0.05,
    glow: "rgba(255, 236, 200, 0.6)",
    wash: [
      "rgba(247, 178, 59, 0.62)",
      "rgba(242, 85, 44, 0.36)",
      "rgba(232, 137, 181, 0.2)",
    ],
  },
} as const;

function advance(ch: string) {
  const code = ch.charCodeAt(0);
  return (code >= 32 && code < 127 ? ONEST_500[code - 32] : 620) / 1000;
}

function textEm(s: string) {
  let w = 0;
  for (let i = 0; i < s.length; i++) {
    if (i > 0) w += KERN.get(s[i - 1] + s[i]) ?? 0;
    w += advance(s[i]) + TRACK;
  }
  return w;
}

function layoutWord(chars: string[]) {
  const xs: number[] = [];
  let x = 0;
  chars.forEach((ch, i) => {
    if (i > 0) x += KERN.get(chars[i - 1] + ch) ?? 0;
    xs.push(x);
    x += advance(ch) + TRACK;
  });
  return { xs, total: x };
}

function mapLetters(a: string[], b: string[]) {
  const used = new Array<boolean>(a.length).fill(false);
  const src = new Array<number>(b.length).fill(-1);
  b.forEach((ch, j) => {
    if (a[j] === ch) {
      src[j] = j;
      used[j] = true;
    }
  });
  const pick = (j: number, same: (x: string, y: string) => boolean) => {
    let best = -1;
    let bestD = Number.POSITIVE_INFINITY;
    a.forEach((ch, i) => {
      if (used[i] || !same(ch, b[j])) return;
      const d = Math.abs(i - j);
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    });
    if (best >= 0) used[best] = true;
    return best;
  };
  b.forEach((_, j) => {
    if (src[j] < 0) src[j] = pick(j, (x, y) => x === y);
  });
  b.forEach((_, j) => {
    if (src[j] < 0)
      src[j] = pick(j, (x, y) => x.toLowerCase() === y.toLowerCase());
  });
  const orphans = a.map((_, i) => i).filter((i) => !used[i]);
  return { src, orphans };
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={23}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

interface Glyph {
  key: string;
  ch: string;
  x0: number;
  x1: number;
  start: number;
  lift: number;
  over: boolean;
  fadeIn: boolean;
  fadeOut: boolean;
}

function typoFixDuration(wrong = "Lanuch") {
  return (
    SWAP_AT +
    Math.max(0, wrong.length - 1) * SWAP_STAGGER +
    TRAVEL +
    RULE_DELAY +
    RULE_LEN +
    HOLD
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function TypoFixBase({
  wrong = "Lanuch",
  correct = "Launch",
  before = "",
  after = "day",
  fixAt = SWAP_AT,
  errorColor,
  accent = "#3B5BFD",
  ink,
  background,
  fontFamily = sans,
  grain = true,
  scale = 1,
  delay = 0,
  theme = "dark",
  speed = 1,
}: TypoFixProps) {
  const glide = useGlide();
  const t = Math.max(0, useCurrentFrame() - delay) * speed;
  const { width: W, height: H, fps } = useVideoConfig();
  const c = THEMES[theme];
  const fg = ink ?? c.fg;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);
  const clipId = `tf${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;

  const a = useMemo(() => Array.from(wrong), [wrong]);
  const b = useMemo(() => Array.from(correct), [correct]);
  const la = useMemo(() => layoutWord(a), [a]);
  const lb = useMemo(() => layoutWord(b), [b]);
  const beforeW = before ? textEm(before) + SPACE : 0;
  const afterW = after ? SPACE + textEm(after) : 0;

  const glyphs = useMemo<Glyph[]>(() => {
    const { src, orphans } = mapLetters(a, b);
    let order = 0;
    const list: Glyph[] = b.map((ch, j) => {
      const i = src[j];
      const x1 = lb.xs[j];
      if (i < 0)
        return {
          key: `in-${j}`,
          ch,
          x0: x1,
          x1,
          start: fixAt,
          lift: 0,
          over: true,
          fadeIn: true,
          fadeOut: false,
        };
      const x0 = la.xs[i];
      const dx = x1 - x0;
      const moving = Math.abs(dx) > 0.02;
      return {
        key: `m-${i}`,
        ch,
        x0,
        x1,
        start: fixAt + (moving ? order++ * SWAP_STAGGER : 0),
        lift: moving ? Math.min(0.62, Math.max(0.44, Math.abs(dx) * 0.85)) : 0,
        over: dx > 0,
        fadeIn: false,
        fadeOut: false,
      };
    });
    for (const i of orphans)
      list.push({
        key: `o-${i}`,
        ch: a[i],
        x0: la.xs[i],
        x1: la.xs[i],
        start: fixAt,
        lift: 0,
        over: false,
        fadeIn: false,
        fadeOut: true,
      });
    return list.sort((m, n) => Number(m.over) - Number(n.over));
  }, [a, b, la, lb, fixAt]);

  const swapEnd = Math.max(...glyphs.map((g) => g.start)) + TRAVEL;
  const fix = EASE_IO(interpolate(t, [fixAt, swapEnd], [0, 1], CLAMP));
  const wordW = la.total + (lb.total - la.total) * fix;
  const maxTotal = beforeW + Math.max(la.total, lb.total) - TRACK + afterW;
  const F = Math.min(H * 0.27, (W * 0.8) / Math.max(maxTotal, 0.1));
  const total = beforeW + wordW - TRACK + afterW;
  const left = -total / 2;
  const wordLeft = left + beforeW;
  const baseline = H / 2 + (CAP * F) / 2;

  const enterAt = (k: number, tt: number) =>
    EASE_OUT(
      interpolate(
        tt,
        [k * ENTER_STAGGER, k * ENTER_STAGGER + ENTER_LEN],
        [0, 1],
        CLAMP,
      ),
    );
  const enter = (k: number) => enterAt(k, t);
  const wordEnter = enter(before ? 1 : 0);
  // Whether a value in px is still travelling, against the neighbouring frames.
  const stirs = (at: (tt: number) => number) =>
    Math.abs(at(t + 1) - at(t)) > 1e-3 || Math.abs(at(t) - at(t - 1)) > 1e-3;
  const entering = (k: number) => stirs((tt) => enterAt(k, tt) * 0.2 * F);

  const ulY = baseline + 0.19 * F;
  const ulX0 = W / 2 + wordLeft * F;
  const ulX1 = W / 2 + (wordLeft + la.total - TRACK) * F;
  const amp = 0.036 * F;
  const wave = 0.13 * F;
  const pts: string[] = [];
  for (let x = ulX0; x <= ulX1 + 0.5; x += 2) {
    const y = ulY + amp * Math.sin(((x - ulX0) / wave) * Math.PI * 2);
    pts.push(`${x.toFixed(1)},${y.toFixed(1)}`);
  }
  const draw = EASE_OUT(
    interpolate(t, [SQUIGGLE_AT, SQUIGGLE_AT + SQUIGGLE_LEN], [0, 1], CLAMP),
  );
  const retractAt = swapEnd - RETRACT_LEN + 2;
  const retract = EASE_IO(
    interpolate(t, [retractAt, retractAt + RETRACT_LEN], [0, 1], CLAMP),
  );
  const clipL = ulX0 - amp + (ulX1 - ulX0 + 2 * amp) * retract;
  const clipR = ulX0 - amp + (ulX1 - ulX0 + 2 * amp) * draw;

  const ruleAt = swapEnd + RULE_DELAY;
  const rule = EASE_OUT(
    interpolate(t, [ruleAt, ruleAt + RULE_LEN], [0, 1], CLAMP),
  );
  const ruleT = Math.max(3, 0.045 * F);
  const ruleX0 = W / 2 + wordLeft * F;
  const ruleW = (lb.total - TRACK) * F;
  const tickAt = (tt: number) =>
    tt >= swapEnd
      ? Math.sin(
          Math.PI *
            Math.min(
              1,
              spring({
                frame: tt - swapEnd,
                fps,
                config: { damping: 14, stiffness: 220, mass: 0.6 },
              }),
            ),
        )
      : 0;
  const tick = tickAt(t);

  const textStyle = {
    position: "absolute" as const,
    top: `${-ASC}em`,
    letterSpacing: `${TRACK}em`,
    whiteSpace: "pre" as const,
    color: fg,
  };

  // The light drifts a few percent across the shot.
  const drift = interpolate(t, [0, swapEnd + RULE_LEN + HOLD], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const gx = 10 + 5 * drift;
  const gy = 8 + 3 * drift;
  const ground = [
    `radial-gradient(48% 42% at ${gx.toFixed(2)}% ${gy.toFixed(2)}%, ${c.glow} 0%, transparent 60%)`,
    `linear-gradient(${(150 - 4 * drift).toFixed(2)}deg, ${c.wash[0]} 0%, ${c.wash[1]} 20%, ${c.wash[2]} 40%, transparent 62%)`,
  ].join(", ");

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {background === undefined ? (
        <div style={{ position: "absolute", inset: 0, background: ground }} />
      ) : null}
      <ScaleLayer scale={scale}>
        <svg
          width={W}
          height={H}
          style={{ position: "absolute", inset: 0 }}
          aria-hidden
        >
          <defs>
            <clipPath id={clipId}>
              <rect
                x={clipL}
                y={ulY - amp * 3}
                width={Math.max(0, clipR - clipL)}
                height={amp * 6}
              />
            </clipPath>
          </defs>
          {draw > 0 && retract < 1 ? (
            <polyline
              points={pts.join(" ")}
              fill="none"
              stroke={errorColor ?? c.error}
              strokeWidth={Math.max(2, 0.03 * F)}
              strokeLinecap="round"
              strokeLinejoin="round"
              clipPath={`url(#${clipId})`}
            />
          ) : null}
        </svg>
        {rule > 0 ? (
          <div
            style={{
              position: "absolute",
              left: ruleX0,
              top: ulY - ruleT / 2,
              width: ruleW * rule,
              height: ruleT,
              borderRadius: ruleT / 2,
              background: accent,
            }}
          />
        ) : null}
        <div
          style={{
            position: "absolute",
            left: W / 2,
            top: baseline,
            fontFamily,
            fontWeight: 500,
            fontSize: F,
            lineHeight: LINE,
            fontKerning: "none",
          }}
        >
          {before ? (
            <div
              style={{
                ...textStyle,
                left: `${left}em`,
                fontKerning: "normal",
                opacity: enter(0),
                transform: `translateY(${(1 - enter(0)) * 0.2}em)${glide(entering(0))}`,
              }}
            >
              {before}
            </div>
          ) : null}
          <div
            style={{
              position: "absolute",
              left: `${wordLeft}em`,
              top: 0,
              opacity: wordEnter,
              // The glyphs inside swap on arcs of their own; this one tilt
              // covers them too.
              transform: `translateY(${(1 - wordEnter) * 0.2 - tick * 0.035}em)${glide(
                entering(before ? 1 : 0) ||
                  stirs((tt) => tickAt(tt) * 0.035 * F) ||
                  glyphs.some((g) =>
                    stirs(
                      (tt) =>
                        Math.sin(
                          Math.PI *
                            EASE_IO(
                              interpolate(
                                tt,
                                [g.start, g.start + TRAVEL],
                                [0, 1],
                                CLAMP,
                              ),
                            ),
                        ) *
                        g.lift *
                        F,
                    ),
                  ),
              )}`,
            }}
          >
            {glyphs.map((g) => {
              const p = EASE_IO(
                interpolate(t, [g.start, g.start + TRAVEL], [0, 1], CLAMP),
              );
              const arc = Math.sin(Math.PI * p);
              const x = g.x0 + (g.x1 - g.x0) * p;
              const y = g.over ? -g.lift * arc : g.lift * 0.85 * arc;
              const scale = g.lift
                ? g.over
                  ? 1 + 0.08 * arc
                  : 1 - 0.08 * arc
                : 1;
              let opacity = 1;
              if (g.fadeIn) opacity = interpolate(p, [0.4, 1], [0, 1], CLAMP);
              if (g.fadeOut) opacity = interpolate(p, [0, 0.6], [1, 0], CLAMP);
              const color =
                g.lift && !g.over
                  ? interpolateColors(arc, [0, 1], [fg, c.dim])
                  : fg;
              return (
                <div
                  key={g.key}
                  style={{
                    ...textStyle,
                    left: 0,
                    color,
                    opacity,
                    transform: `translate(${x}em, ${y}em) scale(${scale})`,
                    transformOrigin: `${advance(g.ch) / 2}em ${ASC}em`,
                  }}
                >
                  {g.ch}
                </div>
              );
            })}
          </div>
          {after ? (
            <div
              style={{
                ...textStyle,
                left: `${wordLeft + wordW + SPACE}em`,
                fontKerning: "normal",
                opacity: enter(before ? 2 : 1),
                transform: `translateY(${(1 - enter(before ? 2 : 1)) * 0.2}em)${glide(entering(before ? 2 : 1))}`,
              }}
            >
              {after}
            </div>
          ) : null}
        </div>
      </ScaleLayer>
      {grain ? <Grain opacity={c.grain} /> : null}
    </AbsoluteFill>
  );
}

