const ELEMENT_PROP_KEYS = new Set(["theme","wrong","correct","before","after","fixAt","accent","errorColor","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  wrong: "Lanuch",
  correct: "Launch",
  before: "",
  after: "day",
  fixAt: 44,
  accent: "#3B5BFD",
  fontFamily: "Onest",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type TypoFixElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof TypoFixBase>;

const TypoFixInner = forwardRef<
  HTMLDivElement,
  TypoFixElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<TypoFix>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <TypoFixBase
          {...(componentProps as unknown as ComponentProps<typeof TypoFixBase>)}
        />
      </div>
    </Sequence>
  );
});

export const TypoFix = Interactive.withSchema({
  Component: TypoFixInner,
  componentName: "<TypoFix>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
